-- Restore only five already-reviewed authenticated-only contracts.
-- Public-schema default service EXECUTE is not a new accepted permission.
do $acl_contract$
declare spec record;p pg_proc;actual_meta jsonb;expected_acl jsonb;actual_acl jsonb;with_default_service jsonb;prior_path text:=current_setting('search_path');
begin
 perform pg_catalog.set_config('search_path','',true);
 for spec in select key signature,value expected from jsonb_each('{"public.confirm_and_apply_trip_proposal(uuid,text,text)":{"source":"1103f421e240cb50f45d603b93e4b9cb4363ff0efa66aa1bc694b0d34014c3ee","definition":"fd5bfbca0bbc8116d3c21df4e1577144ff5879454d18e3237710d270ca2e7f52","owner":"postgres","secdef":true,"acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=public","TimeZone=UTC"],"kind":"f","language":"plpgsql"},"public.create_trip_proposal_patch(uuid,jsonb)":{"source":"b07a3697dce2d77dc6066c14441e1ffcadb034d1b158014d23ff1f81cfc1a4b3","definition":"554cc86ac4b71f00f750f4e617cac73dbf2ded0dd3bff5f4643274f285256542","owner":"postgres","secdef":true,"acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=pg_catalog, public, pg_temp"],"kind":"f","language":"plpgsql"},"public.native_session_v2(text,uuid)":{"source":"213e2e29b3d9eac1a73dd7bbf5afde3eb0b7de1a2d47d5073856ba3b8cded389","definition":"e6d68643eda3d65c6c1980e7599009d581d722554c22adc6b76df4208617851f","owner":"postgres","secdef":false,"acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=\"\""],"kind":"f","language":"sql"},"public.read_trip_proposal_v2(uuid)":{"source":"6a7fec990eef1e980d22ae28b73f85d0ee2eae1119c1cc9f9de10c04602176ab","definition":"589cb8a0957e780fd0652fac99b97f402b6b08de20d0acabbca7e289d118b5f9","owner":"postgres","secdef":false,"acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=\"\"","TimeZone=UTC"],"kind":"f","language":"sql"},"public.reject_trip_proposal_v2(uuid)":{"source":"e9eacb99ca1a23078a6f1be9cdf0444c73edd88213e15f7881aa66afe39005d7","definition":"6a92a7d8cfcec91f863f885a54ba08df0720149dc41c94db2bc4be242b042d24","owner":"postgres","secdef":true,"acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=\"\""],"kind":"f","language":"plpgsql"}}'::jsonb) order by key loop
  select * into p from pg_proc where oid=to_regprocedure(spec.signature);
  select jsonb_build_object('source',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'definition',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),'owner',pg_get_userbyid(p.proowner),'secdef',p.prosecdef,'acl',p.proacl::text,'config',p.proconfig,'kind',p.prokind::text,'language',l.lanname) into actual_meta from pg_language l where l.oid=p.prolang;
  if p.oid is null or (actual_meta-'acl') is distinct from (spec.expected-'acl') then raise exception 'CANONICAL_PLACE_AUTH_ONLY_SOURCE_MISMATCH %',spec.signature;end if;
  select jsonb_agg(v order by v::text collate "C") into expected_acl from(select jsonb_build_array(pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) v from aclexplode((spec.expected->>'acl')::aclitem[])a)q;
  select jsonb_agg(v order by v::text collate "C") into actual_acl from(select jsonb_build_array(pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) v from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a)q;
  select jsonb_agg(v order by v::text collate "C") into with_default_service from jsonb_array_elements(expected_acl||jsonb_build_array(jsonb_build_array('postgres','service_role','EXECUTE',false)))q(v);
  if actual_acl is distinct from expected_acl and actual_acl is distinct from with_default_service then raise exception 'CANONICAL_PLACE_AUTH_ONLY_ACL_MISMATCH %',spec.signature;end if;
 end loop;
 -- All source and exact ACL tuples validate before any permission is narrowed.
 for spec in select unnest(array['public.confirm_and_apply_trip_proposal(uuid,text,text)','public.create_trip_proposal_patch(uuid,jsonb)','public.native_session_v2(text,uuid)','public.read_trip_proposal_v2(uuid)','public.reject_trip_proposal_v2(uuid)']) signature loop
  if exists(select 1 from pg_proc f cross join lateral aclexplode(f.proacl)a where f.oid=to_regprocedure(spec.signature) and a.grantee=(select oid from pg_roles where rolname='service_role') and a.privilege_type='EXECUTE') then execute format('revoke execute on function %s from service_role',spec.signature);end if;
  if not has_function_privilege('authenticated',spec.signature,'EXECUTE') or has_function_privilege('anon',spec.signature,'EXECUTE') or has_function_privilege('service_role',spec.signature,'EXECUTE') then raise exception 'CANONICAL_PLACE_AUTH_ONLY_ROLE_MISMATCH %',spec.signature;end if;
 end loop;
 perform pg_catalog.set_config('search_path',prior_path,true);
end $acl_contract$;
-- Exact post-auth source qualification bodies from original reader/helpers.
-- No new resolver and no identity substitution. Only called after original Root locks.
CREATE OR REPLACE FUNCTION place_actions_private.ask_knowledge_scope_v1(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare instant timestamptz; result jsonb;
begin
 if not knowledge_review_private.closed_object(p_input,array['city','scene','locale'])
  or coalesce(p_input->>'city','') not in ('shanghai','beijing','guangzhou','chongqing')
  or coalesce(p_input->>'scene','') not in ('arrival','airport_transport','payment','connectivity','public_transport','taxi','rail','attraction','accommodation','emergency')
  or coalesce(p_input->>'locale','') not in ('zh','en') then raise exception 'INVALID_INPUT'; end if;
 perform 1 from knowledge_review_private.publication_settings where singleton and enabled for share;
 if not found then raise exception 'KNOWLEDGE_DISABLED'; end if;
 -- Serialize each read with a committed revocation; a receipt is never permanent eligibility.
 perform p.candidate_id from knowledge_review_private.publications p join knowledge_review_private.statements s on s.candidate_id=p.candidate_id
 where p.state='published' and s.payload->'scope'->'cities' ? (p_input->>'city') and s.payload->'scope'->>'scene'=p_input->>'scene' order by p.candidate_id for share of p;
 instant:=clock_timestamp();
 select coalesce(jsonb_agg(x.row order by x.id),'[]'::jsonb) into result from (
  select p.fact_id id,jsonb_build_object('factId',p.fact_id,'version',1,'assertionId',s.statement_id,'assertionRevision',s.revision,
   'assertion',s.payload->'assertion','scope',s.payload->'scope','text',s.payload->'expressions'->(p_input->>'locale')->>'text',
   'conditions',s.payload->'expressions'->(p_input->>'locale')->'conditions','exclusions',s.payload->'expressions'->(p_input->>'locale')->'exclusions',
   'reviewedAt',c.reviewed_at,'publishedAt',p.published_at,'expiresAt',p.expires_at,
   'sources',(select jsonb_agg(jsonb_build_object('sourceRevisionId',r.id,'sourceKey',r.source_key,'revisionLabel',r.revision_label,'publisher',r.declaration->>'publisher','uri',r.declaration->>'uri','locator',r.declaration->>'locator') order by r.source_key,r.revision_label) from knowledge_review_private.statement_sources ss join knowledge_review_private.source_revisions r on r.id=ss.source_revision_id where ss.candidate_id=c.id)) row
  from knowledge_review_private.publications p join knowledge_review_private.statements s on s.candidate_id=p.candidate_id join knowledge_review_private.candidates c on c.id=p.candidate_id
  where p.state='published' and p.expires_at>instant and c.status='reviewed' and s.payload->'scope'->'cities' ? (p_input->>'city') and s.payload->'scope'->>'scene'=p_input->>'scene'
  order by p.fact_id limit 50
 ) x;
 return jsonb_build_object('schemaVersion','knowledge-read/1','evaluatedAt',instant,'scope',p_input,
  'purpose','trip_planning','recipient','first_party','territory','CN-mainland','status',case when jsonb_array_length(result)>0 then 'available' else 'no_eligible_content' end,'statements',result);
end $function$
;
revoke all on function place_actions_private.ask_knowledge_scope_v1(jsonb) from public,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION place_actions_private.ask_claim_basis_v1(p_statement uuid, p_revision integer, p_hash text, p_city text, p_scene text, p_locale text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare st knowledge_review_private.statements%rowtype;p knowledge_review_private.publications%rowtype;c knowledge_review_private.candidates%rowtype;readback jsonb;found_fact jsonb;sources jsonb;
begin
 select * into st from knowledge_review_private.statements where statement_id=p_statement for share nowait;if not found or st.revision is distinct from p_revision or trip_support_private.hash(st.payload) is distinct from p_hash then return null;end if;
 select * into p from knowledge_review_private.publications where candidate_id=st.candidate_id for share nowait;if not found or p.state<>'published' or p.expires_at<=clock_timestamp() then return null;end if;
 select * into c from knowledge_review_private.candidates where id=st.candidate_id for share nowait;if not found or c.status<>'reviewed' then return null;end if;
 readback:=place_actions_private.ask_knowledge_scope_v1(jsonb_build_object('city',p_city,'scene',p_scene,'locale',p_locale));
 select x into found_fact from jsonb_array_elements(readback->'statements') x where x->>'factId'=p.fact_id::text and x->>'assertionId'=st.statement_id::text and x->>'assertionRevision'=st.revision::text;
 if found_fact is null then return null;end if;
 select coalesce(jsonb_agg(jsonb_build_object('sourceRevisionId',r.id,'revisionLabel',r.revision_label,'snippetHash',r.snippet_hash,'submittedBy',r.submitted_by) order by r.id),'[]'::jsonb) into sources from knowledge_review_private.statement_sources ss join knowledge_review_private.source_revisions r on r.id=ss.source_revision_id where ss.candidate_id=st.candidate_id and r.withdrawn_at is null;
 if jsonb_array_length(sources) not between 1 and 8 or jsonb_array_length(sources)<>(select count(*) from knowledge_review_private.statement_sources where candidate_id=st.candidate_id) then return null;end if;
 return jsonb_build_object('statementId',st.statement_id,'claimRevision',st.revision,'payloadHash',p_hash,'payload',st.payload,'sourceRefs',sources,'sourceDigest',trip_support_private.hash(sources),'receipt',jsonb_build_object('kind','fact','factId',p.fact_id,'version',p.version,'reviewedAt',c.reviewed_at,'expiresAt',p.expires_at));
exception when lock_not_available then return null;end $function$
;
revoke all on function place_actions_private.ask_claim_basis_v1(uuid,integer,text,text,text,text) from public,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION place_actions_private.ask_mapping_basis_v1(p_mapping uuid, p_require_approved boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m trip_support_private.entity_mappings%rowtype;p public.canonical_pois%rowtype;basis jsonb;member_revision bigint;
begin
 select * into m from trip_support_private.entity_mappings where id=p_mapping;if not found or p_require_approved and m.status<>'approved' then return null;end if;
 select * into p from public.canonical_pois where id=m.canonical_poi_id for share nowait;if not found or trip_support_private.hash(to_jsonb(p))<>m.canonical_hash then return null;end if;
 if p_require_approved then select revision into member_revision from knowledge_review_private.members where actor_id=m.reviewer_id and active for share nowait;if member_revision is distinct from m.reviewer_member_revision then return null;end if;end if;
 basis:=place_actions_private.ask_claim_basis_v1(m.statement_id,m.claim_revision,m.payload_hash,m.basis_metadata->>'city',m.basis_metadata->>'scene',m.basis_metadata->>'locale');if basis is null or basis->>'sourceDigest'<>m.source_digest or basis->'sourceRefs' is distinct from m.source_refs then return null;end if;
 return basis||jsonb_build_object('mappingId',m.id,'mappingVersion',m.version,'mappingDigest',m.request_digest,'canonicalPoiId',m.canonical_poi_id);
exception when lock_not_available then return null;end $function$
;
revoke all on function place_actions_private.ask_mapping_basis_v1(uuid,boolean) from public,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION place_actions_private.ask_sources_v1(poi uuid, loc text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare m trip_support_private.entity_mappings%rowtype;b jsonb;c jsonb;scope text;rows jsonb:='[]';n integer:=0;expiry timestamptz:=clock_timestamp()+interval '30 seconds';
begin
 -- The publication reader being disabled is unavailable, not a complete empty result.
 perform 1 from knowledge_review_private.publication_settings where singleton and enabled for share;
 if not found then return jsonb_build_object('status','unavailable','entries','[]'::jsonb,'expiresAt',expiry);end if;
 for m in select * from trip_support_private.entity_mappings where canonical_poi_id=poi and status='approved' and basis_metadata->>'locale'=loc order by id limit 501 for share loop
  n:=n+1;if n>500 then return jsonb_build_object('status','unavailable','entries','[]'::jsonb,'expiresAt',expiry);end if;
  if m.version>2147483647 then return jsonb_build_object('status','unavailable','entries','[]'::jsonb,'expiresAt',expiry);end if;
  b:=place_actions_private.ask_mapping_basis_v1(m.id);if b is null then continue;end if;
  scope:=case b->'payload'->'assertion'->>'predicate' when 'located_at' then 'address_reference' when 'opens_during' then 'opening_window_reference' end;
  c:=trip_support_private.typed_claim(b,scope);if c is null then continue;end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('mappingId',m.id,'mappingVersion',m.version,'mappingDigest',m.request_digest,'statementId',m.statement_id,'claimRevision',m.claim_revision,'payloadHash',m.payload_hash,'sourceDigest',m.source_digest,'scope',scope,'claim',c,'city',m.basis_metadata->>'city','scene',m.basis_metadata->>'scene','locale',loc));
  expiry:=least(expiry,(b->'receipt'->>'expiresAt')::timestamptz);
  if jsonb_array_length(rows)>24 then return jsonb_build_object('status','unavailable','entries','[]'::jsonb,'expiresAt',expiry);end if;
 end loop;
 return jsonb_build_object('status','complete','entries',rows,'expiresAt',expiry);
exception when lock_not_available then return jsonb_build_object('status','unavailable','entries','[]'::jsonb,'expiresAt',expiry);end $function$
;
revoke all on function place_actions_private.ask_sources_v1(uuid,text) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_uuid_v1(v jsonb) returns boolean language sql immutable set search_path='' as $$
 select coalesce(jsonb_typeof(v)='string' and v#>>'{}' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',false)
$$;
revoke all on function place_actions_private.ask_uuid_v1(jsonb) from public,anon,authenticated,service_role;
create or replace function place_actions_private.ask_expectation_shape_v1(e jsonb) returns boolean language plpgsql immutable set search_path='' as $$
begin
 if not place_actions_private.exact_v1(e,array['tripId','headVersion','canonicalPoiId','provider','providerPoiId','mappingDigest','contextDigest','referenceId','locale'])
 or not place_actions_private.ask_uuid_v1(e->'tripId') or not place_actions_private.ask_uuid_v1(e->'canonicalPoiId') or not place_actions_private.revision_v1(e->'headVersion')
 or not place_actions_private.selection_v1(jsonb_set(e-array['tripId','headVersion','mappingDigest','contextDigest','referenceId','locale'],'{canonicalPoiId}',to_jsonb(lower(e->>'canonicalPoiId'))))
 or coalesce(e->>'locale','') not in('zh','en') or jsonb_typeof(e->'mappingDigest') is distinct from 'string' or e->>'mappingDigest' !~ '^[a-f0-9]{64}$'
 or jsonb_typeof(e->'contextDigest') is distinct from 'string' or e->>'contextDigest' !~ '^[a-f0-9]{64}$'
 or (e->'referenceId'<>'null'::jsonb and not place_actions_private.ask_uuid_v1(e->'referenceId')) then return false;end if;
 return true;
end $$;
revoke all on function place_actions_private.ask_expectation_shape_v1(jsonb) from public,anon,authenticated,service_role;

-- AGENT005_REAL_SQL_IMPLEMENTATION: private current qualification, no new resolver or ordinary grant.
CREATE OR REPLACE FUNCTION place_actions_private.ask_context_v1(u uuid, actor_session uuid, p_trip uuid, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare t public.trips%rowtype;m jsonb;s place_actions_private.saved_places%rowtype;r uuid;saved jsonb;basis jsonb;src jsonb;stamp timestamptz;snapshot jsonb;
begin
 if u is null or actor_session is null or not exists(select 1 from auth.sessions where id=actor_session and user_id=u) then raise exception 'UNAUTHENTICATED';end if;
 if p_input->>'action'='saved' then return place_actions_private.saved_v1(p_trip,p_input,u);end if;
 if not place_actions_private.valid_v1(p_input,true) then raise exception 'INVALID_INPUT';end if;
 select * into t from public.trips where id=p_trip and owner_id=u for share;if not found then raise exception 'FORBIDDEN';end if;
 if exists(select 1 from public.trip_archives where trip_id=t.id) or exists(select 1 from privacy_private.trip_deletions where trip_id=t.id) then return jsonb_build_object('kind','unavailable','reason','ARCHIVED');end if;
 if t.head_version<>(p_input->>'expectedTripVersion')::numeric then return jsonb_build_object('kind','unavailable','reason','STALE_TRIP_VERSION');end if;
 if (select count(*) from public.trip_place_references where trip_id=t.id)>100 or (select count(*) from public.trip_days where trip_id=t.id)>100 or (select count(*) from public.trip_items where trip_id=t.id)>500 then return jsonb_build_object('kind','unavailable','reason','CAPACITY');end if;
 m:=place_actions_private.mapping_v1(p_input->'selection');if m is null then return jsonb_build_object('kind','unavailable','reason',case when exists(select 1 from public.canonical_pois where id=(p_input->'selection'->>'canonicalPoiId')::uuid) then 'MAPPING_CHANGED' else 'PLACE_NOT_FOUND' end);end if;
 select * into s from place_actions_private.saved_places where owner_id=u and trip_id=t.id and canonical_poi_id=(p_input->'selection'->>'canonicalPoiId')::uuid for share;
 if found then
  perform 1 from public.trip_place_references where id=s.reference_id and trip_id=t.id and owner_id=u and canonical_poi_id=s.canonical_poi_id and reference_kind='canonical';if not found then raise exception 'PLACE_ACTION_UNAVAILABLE';end if;
  saved:=jsonb_build_object('referenceId',s.reference_id,'revision',s.revision,'status',s.status,'mappingDigest',s.mapping_digest);r:=s.reference_id;
 else select id into r from public.trip_place_references where trip_id=t.id and owner_id=u and reference_kind='canonical' and canonical_poi_id=(p_input->'selection'->>'canonicalPoiId')::uuid order by created_at,id limit 1;end if;
 snapshot:=place_actions_private.snapshot_v1(t.id,t.title,t.head_version);
 if place_actions_private.utf16_length_v1(m->>(p_input->>'locale'))>160 or place_actions_private.utf16_length_v1(t.title)>160 or exists(select 1 from public.trip_items where trip_id=t.id and place_actions_private.utf16_length_v1(title)>160) then return jsonb_build_object('kind','unavailable','reason','CAPACITY');end if;
 src:=place_actions_private.ask_sources_v1((p_input->'selection'->>'canonicalPoiId')::uuid,p_input->>'locale');
 basis:=jsonb_build_object('kind','place_action_context','tripId',t.id,'tripVersion',t.head_version,'selection',p_input->'selection','mappingDigest',m->>'digest','snapshot',snapshot,'displayTitle',m->>(p_input->>'locale'),'referenceId',r,'saved',saved,'sourceCandidates',src->'entries','sourceCandidatesStatus',src->>'status');
 stamp:=clock_timestamp();
 return basis||jsonb_build_object('contextDigest',place_actions_private.hash_v1(jsonb_build_object('owner',u,'session',actor_session::text,'basis',basis)),'evaluatedAt',recovery_private.ms_v1(stamp),'expiresAt',recovery_private.ms_v1(least(stamp+interval '30 seconds',(src->>'expiresAt')::timestamptz)));
exception when lock_not_available then raise exception 'PLACE_ACTION_UNAVAILABLE';end $function$
;
revoke all on function place_actions_private.ask_context_v1(uuid,uuid,uuid,jsonb) from public,anon,authenticated,service_role;

-- The helper is private and called only after original owner/session/worker locks.
-- This reads the original mapping/source chain, never names or model output.
create or replace function place_actions_private.ask_basis_v1(u uuid,s uuid,e jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v jsonb;rows jsonb;subject text;city text;scene text;begin
 if not place_actions_private.ask_expectation_shape_v1(e) then raise exception 'INVALID_INPUT';end if;
 v:=place_actions_private.ask_context_v1(u,s,(e->>'tripId')::uuid,jsonb_build_object('action','context','expectedTripVersion',e->'headVersion','selection',jsonb_set(e-array['tripId','headVersion','mappingDigest','contextDigest','referenceId','locale'],'{canonicalPoiId}',to_jsonb(lower(e->>'canonicalPoiId'))),'locale',e->'locale'));
 if v->>'kind' is distinct from 'place_action_context' or v->'mappingDigest' is distinct from e->'mappingDigest'
 or v->'contextDigest' is distinct from e->'contextDigest' or (v->>'referenceId')::uuid is distinct from (e->>'referenceId')::uuid
 then raise exception 'MAPPING_CHANGED';end if;
 if v->>'sourceCandidatesStatus' is distinct from 'complete' or jsonb_array_length(v->'sourceCandidates')=0 then raise exception 'PLACE_ASK_SOURCE_UNAVAILABLE';end if;
 rows:=v->'sourceCandidates';
 if exists(select 1 from jsonb_array_elements(rows)x where x->>'locale' is distinct from e->>'locale'
 or x->>'city' not in('shanghai','beijing','guangzhou','chongqing') or nullif(x->'claim'->>'subjectId','') is null or nullif(x->>'scene','') is null)
 or (select count(distinct jsonb_build_array(x->'claim'->'subjectId',x->'city',x->'scene',x->'locale')) from jsonb_array_elements(rows)x)<>1 then raise exception 'PLACE_ASK_SELECTION_AMBIGUOUS';end if;
 select x->'claim'->>'subjectId',x->>'city',x->>'scene' into subject,city,scene from jsonb_array_elements(rows)x limit 1;
 return jsonb_build_object('subjectId',subject,'city',city,'scene',scene,'sourceDigest',place_actions_private.hash_v1(rows));
end $$;
revoke all on function place_actions_private.ask_basis_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_proof_shape_v1(v jsonb) returns boolean language sql immutable set search_path='' as $$
 select coalesce(place_actions_private.exact_v1(v,array['schemaVersion','operationId','scopeKind','scopeId','operation','requestDigest','expectation','basis','originalReceipt'])
 and place_actions_private.ask_expectation_shape_v1(v->'expectation')
 and place_actions_private.exact_v1(v->'operation',array['operationId','scopeKind','scopeId','messageId','turnId'])
 and v->'operation'->'operationId'=v->'operationId' and v->'operation'->'scopeId'=v->'scopeId' and v->'operation'->'scopeKind'=v->'scopeKind'
 and v->'operation'->'messageId'='null'::jsonb and v->'operation'->'turnId'=v->'originalReceipt'->'turnId'
 and v->'basis'->'city' is not null and v->'expectation'->'locale' is not null
 and v->>'schemaVersion'='canonical-place-proof/1' and v->>'scopeKind'='thread'
 and place_actions_private.ask_uuid_v1(v->'operationId') and place_actions_private.ask_uuid_v1(v->'scopeId')
 and jsonb_typeof(v->'requestDigest')='string' and v->>'requestDigest' ~ '^[a-f0-9]{64}$'
 and place_actions_private.exact_v1(v->'basis',array['subjectId','city','scene','sourceDigest'])
 and v->'basis'->>'city' in('shanghai','beijing','guangzhou','chongqing')
 and jsonb_typeof(v->'basis'->'subjectId')='string' and length(v->'basis'->>'subjectId') between 1 and 160
 and jsonb_typeof(v->'basis'->'scene')='string' and length(v->'basis'->>'scene') between 1 and 80
 and jsonb_typeof(v->'basis'->'sourceDigest')='string' and v->'basis'->>'sourceDigest' ~ '^[a-f0-9]{64}$'
 and place_actions_private.exact_v1(v->'originalReceipt',array['version','kind','turnId','reused','serviceTaskId','scopeVersion','relationship','parentTurnId'])
 and v->'originalReceipt'->>'kind'='accepted' and v->'originalReceipt'->'version'='2'::jsonb
 and v->'originalReceipt'->'reused'='false'::jsonb
 and place_actions_private.ask_uuid_v1(v->'originalReceipt'->'turnId') and place_actions_private.ask_uuid_v1(v->'originalReceipt'->'serviceTaskId')
 and v->'originalReceipt'->'scopeVersion'='1'::jsonb and v->'originalReceipt'->>'relationship' in('new_goal','clarification','repair')
 and (v->'originalReceipt'->'parentTurnId'='null'::jsonb or place_actions_private.ask_uuid_v1(v->'originalReceipt'->'parentTurnId'))
 and ((v->'originalReceipt'->>'relationship'='new_goal')=(v->'originalReceipt'->'parentTurnId'='null'::jsonb)),false)
$$;
revoke all on function place_actions_private.ask_proof_shape_v1(jsonb) from public,anon,authenticated,service_role;
alter table turn_private.grounded_turns add column selected_place_request jsonb;
alter table turn_private.grounded_turns add constraint grounded_selected_place_request_shape check(selected_place_request is null or place_actions_private.ask_proof_shape_v1(selected_place_request));

create or replace function place_actions_private.ask_root_current_v1(tid uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare g turn_private.grounded_turns%rowtype;c turn_private.text_content%rowtype;w turn_private.work%rowtype;p jsonb;b jsonb;begin
 select * into g from turn_private.grounded_turns where turn_id=tid;
 if not found or g.selected_place_request is null then return null;end if;
 p:=g.selected_place_request;
 if not place_actions_private.ask_proof_shape_v1(p) then return null;end if;
 select * into w from turn_private.work where turn_id=tid and owner_id=g.owner_id;
 if not found then return null;end if;
 if exists(select 1 from identity_private.mobile_attempts where session_id=w.session_id) and not exists(select 1 from identity_private.mobile_attempts x join identity_private.mobile_accounts a on a.owner_id=x.owner_id and a.session_id=x.session_id and a.epoch=x.epoch where x.owner_id=g.owner_id and x.session_id=w.session_id) then return null;end if;

 select * into c from turn_private.text_content where turn_id=tid and owner_id=g.owner_id and hidden_at is null;
 if not found or not turn_private.text_policy_current(c.policy_id)
 or not exists(select 1 from turn_private.text_consents where owner_id=g.owner_id and policy_id=c.policy_id and consent_id=c.consent_id and revoked_at is null)
 or exists(select 1 from public.turns where id=tid and status='cancelled') or exists(select 1 from turn_private.work where turn_id=tid and state='cancelled')
 or not exists(select 1 from turn_private.service_task_turns st join turn_private.service_tasks t on t.id=st.task_id and t.owner_id=st.owner_id
 join turn_private.text_content root on root.turn_id=t.goal_turn_id and root.owner_id=t.owner_id and root.hidden_at is null
 where st.turn_id=tid and st.owner_id=g.owner_id and st.task_id=g.task_id and st.idempotency_key=(p->>'operationId')::uuid
 and st.relationship=p->'originalReceipt'->>'relationship' and st.parent_turn_id is not distinct from (p->'originalReceipt'->>'parentTurnId')::uuid
 and t.thread_id=(p->>'scopeId')::uuid and c.thread_id=t.thread_id and t.policy_id=c.policy_id and t.consent_id=c.consent_id
 and st.request_digest=encode(sha256(convert_to(jsonb_build_array(c.thread_id,c.turn_id,st.idempotency_key,c.policy_id,c.locale,c.input_text,t.id,t.scope_version,st.relationship,st.parent_turn_id)::text,'UTF8')),'hex'))
 or p->'originalReceipt'->>'turnId' is distinct from tid::text or p->'originalReceipt'->>'serviceTaskId' is distinct from g.task_id::text
 or g.city is distinct from p->'basis'->>'city' or g.locale is distinct from p->'expectation'->>'locale' then return null;end if;
 -- Stored proof is a witness, never a grant. Requalify the original source chain.
 begin b:=place_actions_private.ask_basis_v1(g.owner_id,w.session_id,p->'expectation');
 exception when raise_exception then return null;end;
 if b is distinct from p->'basis' then return null;end if;
 return p;
end $$;
revoke all on function place_actions_private.ask_root_current_v1(uuid) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_bound_v1(tid uuid,token uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
