 end if;
 select * into c from turn_private.text_content where turn_id=tid and owner_id=g.owner_id and hidden_at is null;
 if not found or not turn_private.text_policy_current(c.policy_id)
 or not exists(select 1 from turn_private.text_consents where owner_id=g.owner_id and policy_id=c.policy_id and consent_id=c.consent_id and revoked_at is null)
 or exists(select 1 from public.turns where id=tid and status='cancelled') or exists(select 1 from turn_private.work where turn_id=tid and state='cancelled')
 or not exists(select 1 from turn_private.service_task_turns st join turn_private.service_tasks t on t.id=st.task_id and t.owner_id=st.owner_id
 join turn_private.text_content root on root.turn_id=t.goal_turn_id and root.owner_id=t.owner_id and root.hidden_at is null
 where st.turn_id=tid and st.owner_id=g.owner_id and st.task_id=g.task_id and st.idempotency_key=(p->>'operationId')::uuid
 and st.relationship=p->'originalReceipt'->>'relationship' and st.parent_turn_id is not distinct from (p->'originalReceipt'->>'parentTurnId')::uuid
 and t.thread_id=(p->>'scopeId')::uuid and c.thread_id=t.thread_id and t.policy_id=c.policy_id and t.consent_id=c.consent_id
 and st.request_digest=encode(sha256(convert_to(jsonb_build_array(c.thread_id,c.turn_id,st.idempotency_key,c.policy_id,c.locale,c.input_text,t.id,t.scope_version,st.relationship,st.parent_turn_id)::text,'UTF8')),'hex'))
 or p->'originalReceipt'->>'turnId' is distinct from tid::text or p->'originalReceipt'->>'serviceTaskId' is distinct from g.task_id::text
 or g.city is distinct from p->'basis'->>'city' or g.locale is distinct from p->'expectation'->>'locale' then return null;end if;
 -- Stored proof is a witness, never a grant. Requalify the original source chain.
 begin b:=place_actions_private.ask_basis_v1(g.owner_id,w.session_id,p->'expectation');
 exception when raise_exception then return null;end;
 if b is distinct from p->'basis' then return null;end if;
 return p;
end $$;
revoke all on function place_actions_private.ask_bound_v1(uuid,uuid) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_receipt_v1(tid uuid,p jsonb) returns jsonb language sql immutable set search_path='' as $$
 select jsonb_build_object('schemaVersion','canonical-place-ask/1','kind','accepted','operation',p->'operation','originalReceipt',p->'originalReceipt',
 'binding',jsonb_build_object('turnId',tid,'serviceTaskId',p->'originalReceipt'->'serviceTaskId','goalId',null,'goalVersion',null,'requestDigest',p->'requestDigest','expectation',p->'expectation'),
 'readyForProvider',false,'currentEligibilityRequiresRead',true)
$$;
revoke all on function place_actions_private.ask_receipt_v1(uuid,jsonb) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_submit_v1(request_bytes text) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=place_actions_private.actor_v1();s uuid:=(auth.jwt()->>'session_id')::uuid;v jsonb:=request_bytes::jsonb;r jsonb:=v->'submission';e jsonb:=v->'expectation';b jsonb;old turn_private.grounded_turns%rowtype;receipt jsonb;p jsonb;tid uuid;begin
 if not place_actions_private.exact_v1(v,array['schemaVersion','submission','expectation']) or v->>'schemaVersion' is distinct from 'canonical-place-ask/1' or octet_length(request_bytes)>24000 then raise exception 'INVALID_INPUT';end if;
 -- The original assistant envelope does not admit a Task Turn. Do not invent one.
 if r ? 'conversationId' then return jsonb_build_object('schemaVersion','canonical-place-ask/1','kind','unavailable','reason','original_submission_unsupported','readyForProvider',false);end if;
 if not place_actions_private.exact_v1(r,array['threadId','turnId','idempotencyKey','policyId','locale','text','serviceTask'])
 or not place_actions_private.exact_v1(r->'serviceTask',array['id','scopeVersion','relationship','parentTurnId'])
 or not place_actions_private.ask_uuid_v1(r->'threadId') or not place_actions_private.ask_uuid_v1(r->'turnId') or not place_actions_private.ask_uuid_v1(r->'idempotencyKey')
 or not place_actions_private.ask_uuid_v1(r->'policyId') or not place_actions_private.ask_uuid_v1(r->'serviceTask'->'id')
 or r->'serviceTask'->'scopeVersion' is distinct from '1'::jsonb
 or coalesce(r->'serviceTask'->>'relationship','') not in('new_goal','clarification','repair')
 or ((r->'serviceTask'->>'relationship'='new_goal') is distinct from (r->'serviceTask'->'parentTurnId'='null'::jsonb))
 or (r->'serviceTask'->'parentTurnId'<>'null'::jsonb and not place_actions_private.ask_uuid_v1(r->'serviceTask'->'parentTurnId'))
 or jsonb_typeof(r->'text') is distinct from 'string' or not turn_private.valid_text(r->>'text',4000)
 or coalesce(r->>'locale','') not in('zh','en') or r->'locale' is distinct from e->'locale' then raise exception 'INVALID_INPUT';end if;
 tid:=(r->>'turnId')::uuid;
 -- Account/auth first, mobile UPDATE then 34, then operation/root/Trip/context.
 perform 1 from identity_private.mobile_accounts where owner_id=u for update;
 perform pg_advisory_xact_lock(hashtextextended(u::text,34));
 perform pg_advisory_xact_lock(hashtextextended('selected-place:'||u::text||':'||(r->>'idempotencyKey'),0));
 select g.* into old from turn_private.grounded_turns g where owner_id=u and (selected_place_request->>'operationId')::uuid=(r->>'idempotencyKey')::uuid;
 if found then
  if old.turn_id<>tid or old.selected_place_request->>'requestDigest'<>encode(sha256(convert_to(request_bytes,'UTF8')),'hex') then raise exception 'IDEMPOTENCY_KEY_REUSE';end if;
  if place_actions_private.ask_bound_v1(tid,null) is null then raise exception 'DATA_POLICY_BLOCKED';end if;
  return place_actions_private.ask_receipt_v1(tid,old.selected_place_request);
 end if;
 -- Reject prior admission rather than attaching to already committed ordinary work.
 if exists(select 1 from public.turns where id=tid) or exists(select 1 from turn_private.text_content where turn_id=tid)
 or exists(select 1 from turn_private.service_task_turns where owner_id=u and idempotency_key=(r->>'idempotencyKey')::uuid) then raise exception 'IDEMPOTENCY_KEY_REUSE';end if;
 -- Original admission chooses and meters exactly one Task, retaining all original semantics.
 receipt:=public.submit_service_task_turn((r->>'threadId')::uuid,tid,(r->>'idempotencyKey')::uuid,(r->>'policyId')::uuid,r->>'locale',r->>'text',
 (r->'serviceTask'->>'id')::uuid,(r->'serviceTask'->>'scopeVersion')::integer,r->'serviceTask'->>'relationship',(r->'serviceTask'->>'parentTurnId')::uuid);
 if receipt->>'kind' is distinct from 'accepted' or receipt->'reused' is distinct from 'false'::jsonb then raise exception 'SERVICE_TASK_CONFLICT';end if;
 -- Current-input policy only: no additional source facts/caption enter any model prompt.
 if not exists(select 1 from turn_private.text_policies where id=(r->>'policyId')::uuid and context_mode='current_input_v1') then raise exception 'DATA_POLICY_BLOCKED';end if;
 b:=place_actions_private.ask_basis_v1(u,s,e);
 -- Match the original Native v2 receipt projection; retain its actual identities/relationship.
 receipt:=jsonb_build_object('version',2,'kind',receipt->'kind','turnId',receipt->'turnId','reused',receipt->'reused','serviceTaskId',receipt->'serviceTaskId','scopeVersion',receipt->'scopeVersion','relationship',receipt->'relationship','parentTurnId',receipt->'parentTurnId');
 p:=jsonb_build_object('schemaVersion','canonical-place-proof/1','operationId',(r->>'idempotencyKey')::uuid,'scopeKind','thread','scopeId',(r->>'threadId')::uuid,'operation',jsonb_build_object('operationId',(r->>'idempotencyKey')::uuid,'scopeKind','thread','scopeId',(r->>'threadId')::uuid,'messageId',null,'turnId',tid),'requestDigest',encode(sha256(convert_to(request_bytes,'UTF8')),'hex'),'expectation',e,'basis',b,'originalReceipt',receipt);
 insert into turn_private.grounded_turns(turn_id,owner_id,task_id,city,locale,selected_place_request) values(tid,u,(r->'serviceTask'->>'id')::uuid,b->>'city',r->>'locale',p);
 if place_actions_private.ask_bound_v1(tid,null) is null then raise exception 'DATA_POLICY_BLOCKED';end if;
 return place_actions_private.ask_receipt_v1(tid,p);
exception when raise_exception then
 if SQLERRM in('PLACE_ASK_SOURCE_UNAVAILABLE','PLACE_ASK_SELECTION_AMBIGUOUS') then
  return jsonb_build_object('schemaVersion','canonical-place-ask/1','kind','unavailable','reason',case SQLERRM when 'PLACE_ASK_SELECTION_AMBIGUOUS' then 'selection_ambiguous' else 'source_unavailable' end,'readyForProvider',false);
 end if;raise;
end $$;
revoke all on function place_actions_private.ask_submit_v1(text) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_read_v1(v jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=place_actions_private.actor_v1();g turn_private.grounded_turns%rowtype;p jsonb;current_n jsonb;begin
 if not place_actions_private.exact_v1(v,array['operationId','scopeKind','scopeId','messageId','turnId']) or not place_actions_private.ask_uuid_v1(v->'operationId') or not place_actions_private.ask_uuid_v1(v->'scopeId') or v->>'scopeKind' not in('thread','conversation') or (v->>'scopeKind'='thread' and (v->'messageId'<>'null'::jsonb or not place_actions_private.ask_uuid_v1(v->'turnId'))) or (v->>'scopeKind'='conversation' and (not place_actions_private.ask_uuid_v1(v->'messageId') or (v->'turnId'<>'null'::jsonb and not place_actions_private.ask_uuid_v1(v->'turnId')))) then raise exception 'INVALID_INPUT';end if;
 v:=jsonb_set(jsonb_set(jsonb_set(v,'{operationId}',to_jsonb((v->>'operationId')::uuid)),'{scopeId}',to_jsonb((v->>'scopeId')::uuid)),'{turnId}',coalesce(to_jsonb((v->>'turnId')::uuid),'null'::jsonb));
 select * into g from turn_private.grounded_turns where owner_id=u and selected_place_request->'operationId'=v->'operationId' and selected_place_request->'scopeKind'=v->'scopeKind' and selected_place_request->'scopeId'=v->'scopeId';
 if not found then
 if exists(select 1 from turn_private.grounded_turns where selected_place_request->'operationId'=v->'operationId')
 or exists(select 1 from turn_private.service_task_turns where idempotency_key=(v->>'operationId')::uuid and owner_id<>u)
 or exists(select 1 from public.turns where id=(v->>'turnId')::uuid and owner_id<>u) then raise exception 'FORBIDDEN';end if;
 -- Erasure deletes the sensitive proof, not the authoritative admission/fences.
 -- A missing proof is never evidence that this original operation did not commit.
 if exists(select 1 from turn_private.service_task_turns where owner_id=u and idempotency_key=(v->>'operationId')::uuid)
 or exists(select 1 from turn_private.assistant_messages where owner_id=u and idempotency_key=(v->>'operationId')::uuid)
 or exists(select 1 from public.turns where id=(v->>'turnId')::uuid and owner_id=u)
 or (v->>'turnId' is not null and turn_data_private.fenced_v1('turnIds',(v->>'turnId')::uuid)) then
  return jsonb_build_object('schemaVersion','canonical-place-ask/1','kind','unknown','operation',v,'readyForProvider',false);
 end if;
 return jsonb_build_object('schemaVersion','canonical-place-ask/1','kind','not_submitted','operation',v,'readyForProvider',false);end if;
 if g.selected_place_request->'operation' is distinct from v or not exists(select 1 from turn_private.work where turn_id=g.turn_id and session_id=(auth.jwt()->>'session_id')::uuid) then raise exception 'FORBIDDEN';end if;
 p:=place_actions_private.ask_bound_v1(g.turn_id,null);
 current_n:=case when p is null then jsonb_build_object('kind','unavailable','reason','source_unavailable') else jsonb_build_object('kind','pending') end;
 if p is not null then
  current_n:=public.read_grounded_turn(g.turn_id);
  current_n:=case when current_n->>'kind'='grounded_turn' and current_n->'result'->>'projection'='pending' then jsonb_build_object('kind','pending') when current_n->>'kind'='grounded_turn' and current_n->'result'->>'projection'='current' then jsonb_build_object('kind','grounded','turn',current_n) else jsonb_build_object('kind','unavailable','reason','source_unavailable') end;
 end if;
 return jsonb_build_object('schemaVersion','canonical-place-ask/1','kind','recovered','operation',v,'receipt',place_actions_private.ask_receipt_v1(g.turn_id,g.selected_place_request),'current',current_n,'readyForProvider',false);
end $$;
revoke all on function place_actions_private.ask_read_v1(jsonb) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_history_root_v1(tid uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare g turn_private.grounded_turns%rowtype;c turn_private.text_content%rowtype;w turn_private.work%rowtype;p jsonb;b jsonb;begin
 select * into g from turn_private.grounded_turns where turn_id=tid;
 if not found or g.selected_place_request is null then return null;end if;
 p:=g.selected_place_request;
 if not place_actions_private.ask_proof_shape_v1(p) then return null;end if;
 select * into w from turn_private.work where turn_id=tid and owner_id=g.owner_id;
 if not found then return null;end if;
 if exists(select 1 from identity_private.mobile_attempts where session_id=w.session_id) and not exists(select 1 from identity_private.mobile_attempts x join identity_private.mobile_accounts a on a.owner_id=x.owner_id and a.session_id=x.session_id and a.epoch=x.epoch where x.owner_id=g.owner_id and x.session_id=w.session_id) then return null;end if;
 if auth.uid() is distinct from g.owner_id or auth.jwt()->>'session_id' is distinct from w.session_id::text then return null;end if;
 perform turn_private.text_owner();
 if not turn_private.lock_trip_account_v1(g.owner_id) then return null;end if;
 perform pg_advisory_xact_lock(hashtextextended(g.owner_id::text,34));
 if not turn_private.lock_turn(tid,g.owner_id,w.session_id) then return null;end if;
 select * into c from turn_private.text_content where turn_id=tid and owner_id=g.owner_id and hidden_at is null;
 if not found or not turn_private.text_policy_current(c.policy_id)
 or not exists(select 1 from turn_private.text_consents where owner_id=g.owner_id and policy_id=c.policy_id and consent_id=c.consent_id and revoked_at is null)

 or not exists(select 1 from turn_private.service_task_turns st join turn_private.service_tasks t on t.id=st.task_id and t.owner_id=st.owner_id
 join turn_private.text_content root on root.turn_id=t.goal_turn_id and root.owner_id=t.owner_id and root.hidden_at is null
 where st.turn_id=tid and st.owner_id=g.owner_id and st.task_id=g.task_id and st.idempotency_key=(p->>'operationId')::uuid
 and st.relationship=p->'originalReceipt'->>'relationship' and st.parent_turn_id is not distinct from (p->'originalReceipt'->>'parentTurnId')::uuid
 and t.thread_id=(p->>'scopeId')::uuid and c.thread_id=t.thread_id and t.policy_id=c.policy_id and t.consent_id=c.consent_id
 and st.request_digest=encode(sha256(convert_to(jsonb_build_array(c.thread_id,c.turn_id,st.idempotency_key,c.policy_id,c.locale,c.input_text,t.id,t.scope_version,st.relationship,st.parent_turn_id)::text,'UTF8')),'hex'))
 or p->'originalReceipt'->>'turnId' is distinct from tid::text or p->'originalReceipt'->>'serviceTaskId' is distinct from g.task_id::text
 or g.city is distinct from p->'basis'->>'city' or g.locale is distinct from p->'expectation'->>'locale' then return null;end if;
 -- Root ownership is retained data authority only, never current fact permission.
 return p;
end $$;
revoke all on function place_actions_private.ask_history_root_v1(uuid) from public,anon,authenticated,service_role;

-- Only a currently qualified selected proof may add the existing GroundedResult
-- to an ordinary Task read/history row. Plain NULL rows retain their old bytes.
create or replace function place_actions_private.ask_text_projection_v1(tid uuid,history_row boolean) returns jsonb
language plpgsql security definer set search_path='' as $$
declare q jsonb;p jsonb;g turn_private.grounded_turns%rowtype;c turn_private.text_content%rowtype;state_n text;begin
 if not exists(select 1 from turn_private.grounded_turns where turn_id=tid and selected_place_request is not null) then return null;end if;
 p:=place_actions_private.ask_history_root_v1(tid);
 if p is null then return null;end if;
 q:=public.read_grounded_turn(tid);
 -- Source reads may wait; retained metadata still needs current Root authority.
 p:=place_actions_private.ask_history_root_v1(tid);
 if p is null then return null;end if;
 if q->>'kind' is distinct from 'grounded_turn' or coalesce(q->'result'->>'projection','') not in('pending','current') then
  select * into g from turn_private.grounded_turns where turn_id=tid and owner_id=auth.uid();
  select * into c from turn_private.text_content where turn_id=tid and owner_id=auth.uid() and hidden_at is null;
  select status into state_n from public.turns where id=tid and owner_id=auth.uid();
  q:=jsonb_build_object('kind','grounded_turn','turnId',tid,'threadId',c.thread_id,'locale',c.locale,'input',c.input_text,'outcome',c.output_kind,'output',c.output_text,'status',state_n,'createdAt',c.created_at,
   'result',jsonb_build_object('type','reviewed_answer','city',g.city,'intent',g.intent,'requestScope',g.request_scope,'unansweredNeeds',g.unanswered_needs,'placeSubjectId',g.place_subject_id,'placeName',g.place_name,'placeResolution',g.place_resolution,'originalOutcome',g.original_outcome,'completedAt',g.completed_at,'projection','unavailable','knowledge',null));
 end if;
 if history_row then
  return jsonb_build_object('turnId',q->'turnId','threadId',q->'threadId','locale',q->'locale','input',q->'input','outcome',q->'outcome','output',q->'output','status',q->'status','createdAt',q->'createdAt','result',q->'result','canonicalPlaceProof',p);
 end if;
 return jsonb_build_object('kind','text','schemaVersion','text-turn-v1','turnId',q->'turnId','locale',q->'locale','input',q->'input','outcome',q->'outcome','output',q->'output','result',q->'result','canonicalPlaceProof',p);
end $$;
revoke all on function place_actions_private.ask_text_projection_v1(uuid,boolean) from public,anon,authenticated,service_role;

-- Original text ServiceTask finalization, after the original grounded result is
-- terminal in this transaction. The caller holds account/mobile/34 before Root.
-- No second completion, grant, budget attempt, fee ledger or Task is created.
create or replace function place_actions_private.ask_finish_capacity_v1(p_turn_id uuid,p_kind text,p_text text) returns void
language plpgsql security definer set search_path='' as $$
declare task uuid;task_owner uuid;capacity turn_private.service_task_capacity%rowtype;task_enforced boolean;
begin
 select l.task_id,l.owner_id into task,task_owner from turn_private.service_task_turns l where l.turn_id=p_turn_id;
 if task is null then return;end if;
 if not turn_private.lock_trip_account_v1(task_owner) then raise exception 'SERVICE_TASK_RESULT_UNREADABLE';end if;
 perform pg_advisory_xact_lock(hashtextextended(task_owner::text,34));
 select * into capacity from turn_private.service_task_capacity where task_id=task for update;
 if not found then
  select capacity_enforced into task_enforced from turn_private.service_tasks where id=task;
  if task_enforced then raise exception 'SERVICE_TASK_CAPACITY_CONFLICT';end if;
  return;
 end if;
 if capacity.state<>'reserved' then return;end if;
 if p_kind='answered' then
  if not exists(select 1 from turn_private.text_content c
   join public.turns t on t.id=c.turn_id and t.owner_id=c.owner_id and t.status='completed'
   join public.chat_threads h on h.id=c.thread_id and h.owner_id=c.owner_id and h.status='active'
   join turn_private.text_consents consent on consent.owner_id=c.owner_id and consent.policy_id=c.policy_id and consent.consent_id=c.consent_id and consent.revoked_at is null
   where c.turn_id=p_turn_id and c.owner_id=task_owner and c.hidden_at is null and c.output_kind='answered' and c.output_text=p_text and turn_private.text_policy_current(c.policy_id)) then raise exception 'SERVICE_TASK_RESULT_UNREADABLE';end if;
  if capacity.tier='journey_pass' and not exists(select 1 from public.storekit_grants g
   where g.environment=capacity.grant_environment and g.transaction_id=capacity.grant_transaction_id and g.owner_id=task_owner and g.state='active' and g.starts_at<=capacity.admitted_at and g.ends_at>clock_timestamp()) then raise exception 'SERVICE_TASK_GRANT_UNAVAILABLE';end if;
  update turn_private.service_task_capacity set state='settled',settled_turn_id=p_turn_id,settled_at=clock_timestamp() where task_id=task and state='reserved';
 elsif p_kind in('partial','blocked','technical_failure','cancelled') then
  update turn_private.service_task_capacity set state='released',released_at=clock_timestamp() where task_id=task and state='reserved';
 end if;
 -- Clarification retains the original reservation for the same-Task continuation.
end $$;
revoke all on function place_actions_private.ask_finish_capacity_v1(uuid,text,text) from public,anon,authenticated,service_role;

-- Called solely inside the existing service-role claimer after lock_turn.
create or replace function place_actions_private.ask_claim_current_v1(tid uuid) returns boolean language plpgsql security definer set search_path='' as $$
begin
 return place_actions_private.ask_root_current_v1(tid) is not null;
exception when raise_exception then return false;end $$;
revoke all on function place_actions_private.ask_claim_current_v1(uuid) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_complete_v1(tid uuid,token uuid,intent text,scope text,needs_text text,place_name text) returns jsonb language plpgsql security definer set search_path='' as $$
declare p jsonb:=place_actions_private.ask_bound_v1(tid,token);needs jsonb;q text;result jsonb;begin
 if p is null then return jsonb_build_object('kind','blocked');end if;
 if intent not in('place_address','place_opening_hours','place_address_and_hours') or scope not in('single','additional_needs') or needs_text is null or octet_length(needs_text)>12000 then raise exception 'INVALID_INPUT';end if;
 needs:=needs_text::jsonb;select input_text into q from turn_private.text_content where turn_id=tid;
 if jsonb_typeof(needs) is distinct from 'array' or jsonb_array_length(needs)>6 or (scope='additional_needs')<>(jsonb_array_length(needs)>0)
 or exists(select 1 from jsonb_array_elements(needs)x where jsonb_typeof(x) is distinct from 'string' or length(x#>>'{}') not between 1 and 240 or strpos(q,x#>>'{}')=0)
 or (select count(distinct x) from jsonb_array_elements(needs)x)<>jsonb_array_length(needs) then raise exception 'INVALID_INPUT';end if;
 -- Canonical subject comes only from the original reviewed mapping, never place_name.
 result:=turn_private.complete_selected_grounded_work(tid,token,intent,scope,p->'basis'->>'subjectId');
 if result->>'kind'='finished' then update turn_private.grounded_turns set place_name=null,place_resolution='matched',unanswered_needs=needs where turn_id=tid;end if;
 return result;
end $$;
revoke all on function place_actions_private.ask_complete_v1(uuid,uuid,text,text,text,text) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_schema_v1() returns boolean language sql stable set search_path='' as $$
 select coalesce(exists(select 1 from pg_attribute a where a.attrelid='turn_private.grounded_turns'::regclass and a.attname='selected_place_request' and a.attnum>0 and not a.attisdropped and a.atttypid='jsonb'::regtype and not a.attnotnull and not a.atthasdef and a.attgenerated='' and a.attidentity='')
 and (select pg_get_constraintdef(k.oid) from pg_constraint k where k.conrelid='turn_private.grounded_turns'::regclass and k.conname='grounded_selected_place_request_shape') = 'CHECK (((selected_place_request IS NULL) OR place_actions_private.ask_proof_shape_v1(selected_place_request)))',false)
$$;
revoke all on function place_actions_private.ask_schema_v1() from public,anon,authenticated,service_role;

-- The original source tables and PK fences remain the lifecycle authority.
-- NULL on an old row must disappear before old fingerprint/export serialization.
create or replace function place_actions_private.ask_source_row_v1(rel text,v jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
begin
 if rel<>'turn_private.grounded_turns' or not(v ? 'selected_place_request') then return v;end if;
 if v->'selected_place_request'='null'::jsonb then return v-'selected_place_request';end if;
 if not place_actions_private.ask_proof_shape_v1(v->'selected_place_request') then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
 return v;
end $$;
revoke all on function place_actions_private.ask_source_row_v1(text,jsonb) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_answer_basis_shape_v1(v jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare x jsonb;begin
 if v='null'::jsonb then return true;end if;
 if not place_actions_private.exact_v1(v,array['publications','claims']) or jsonb_typeof(v->'publications') is distinct from 'array' or jsonb_array_length(v->'publications')>50 or jsonb_typeof(v->'claims') is distinct from 'array' or jsonb_array_length(v->'claims')>6 then return false;end if;
 for x in select value from jsonb_array_elements(v->'publications') loop
  if not place_actions_private.exact_v1(x,array['factId','assertionId','revision','payloadHash']) or not place_actions_private.uuid_v1(x->'factId') or not place_actions_private.uuid_v1(x->'assertionId') or not place_actions_private.revision_v1(x->'revision') or (x->>'revision')::integer<1 or jsonb_typeof(x->'payloadHash') is distinct from 'string' or x->>'payloadHash' !~ '^[a-f0-9]{64}$' then return false;end if;
 end loop;
 for x in select value from jsonb_array_elements(v->'claims') loop
  if not place_actions_private.exact_v1(x,array['id','status','reasons','factIds']) or x->>'id' not in('place_address','opening_hours') or x->>'status' not in('covered','unavailable','unresolved_variants')
  or jsonb_typeof(x->'reasons') is distinct from 'array' or jsonb_typeof(x->'factIds') is distinct from 'array' or jsonb_array_length(x->'reasons')>8 or jsonb_array_length(x->'factIds')>50
  or exists(select 1 from jsonb_array_elements(x->'reasons')r where jsonb_typeof(r) is distinct from 'string' or r#>>'{}' not in('missing','expired','revoked','unreviewed','unresolved_variants'))
  or exists(select 1 from jsonb_array_elements(x->'factIds')f where not place_actions_private.uuid_v1(f) or not exists(select 1 from jsonb_array_elements(v->'publications')p where p->'factId'=f)) then return false;end if;
 end loop;
 return true;
end $$;
revoke all on function place_actions_private.ask_answer_basis_shape_v1(jsonb) from public,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.authorize_grounded_dispatch(p_turn_id uuid, p_lease_token uuid, p_policy_id uuid, p_provider text, p_context_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payload jsonb; c turn_private.text_content%rowtype;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and place_actions_private.ask_bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','blocked'); end if;
 payload:=public.read_grounded_work(p_turn_id,p_lease_token);
 if payload->>'kind' is distinct from 'intent_input' or payload->>'policyId' is distinct from p_policy_id::text
   or payload->>'provider' is distinct from p_provider or payload->>'contextDigest' is distinct from p_context_digest then return jsonb_build_object('kind','blocked'); end if;
 select * into c from turn_private.text_content where turn_id=p_turn_id;
 insert into turn_private.text_dispatches(lease_token,turn_id,consent_id,policy_id) values(p_lease_token,p_turn_id,c.consent_id,c.policy_id) on conflict do nothing;
 if not found then return jsonb_build_object('kind','blocked'); end if;
 return jsonb_build_object('kind','authorized');
end $function$
;

CREATE OR REPLACE FUNCTION public.authorize_text_dispatch(p_turn_id uuid, p_lease_token uuid, p_policy_id uuid, p_provider text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c turn_private.text_content%rowtype;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) then return jsonb_build_object('kind','blocked');end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','blocked'); end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode='planning_comparison_v1')
    then return jsonb_build_object('kind','blocked'); end if;
  if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
  select * into c from turn_private.text_content where turn_id=p_turn_id;
  if c.policy_id is distinct from p_policy_id or not exists(select 1 from turn_private.text_policies where id=p_policy_id and provider=p_provider and context_mode='current_input_v1') then return jsonb_build_object('kind','blocked'); end if;
  insert into turn_private.text_dispatches(lease_token,turn_id,consent_id,policy_id) values(p_lease_token,p_turn_id,c.consent_id,c.policy_id) on conflict do nothing;
  if not found then return jsonb_build_object('kind','blocked'); end if;
  return jsonb_build_object('kind','authorized');
end $function$
;

