CREATE OR REPLACE FUNCTION public.cancel_chat_turn(p_turn_id uuid)
 RETURNS TABLE(sequence integer, state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare task uuid; task_owner uuid; cancelled record;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and owner_id=auth.uid() and selected_place_request is not null) then
  perform turn_private.text_owner();
  if not turn_private.lock_trip_account_v1(auth.uid()) then raise exception 'UNAUTHENTICATED';end if;
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,34));
 end if;
  select l.task_id,l.owner_id into task,task_owner from turn_private.service_task_turns l
    where l.turn_id=p_turn_id and l.owner_id=(select auth.uid());
  if task is not null then perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(task_owner::text,34)); end if;
  select * into cancelled from turn_private.cancel_chat_turn_unmetered(p_turn_id);
  if task is not null and cancelled.state='cancelled' then
    update turn_private.service_task_capacity c set state='released',released_at=pg_catalog.clock_timestamp()
      where c.task_id=task and c.owner_id=task_owner and c.state='reserved';
  end if;
  return query select cancelled.sequence::integer,cancelled.state::text;
end $function$
;

CREATE OR REPLACE FUNCTION public.claim_turn_work()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare candidate record; w turn_private.work%rowtype; turn_state text;
begin
  for candidate in select turn_id,owner_id,session_id from turn_private.work q
    where q.execution_mode='text' and not exists(select 1 from turn_private.grounded_turns selected where selected.turn_id=q.turn_id and selected.selected_place_request is not null) and (state='queued' or (state='leased' and expires_at<=clock_timestamp()))
      and not exists(select 1 from turn_private.text_content c join turn_private.text_policies p on p.id=c.policy_id
        where c.turn_id=q.turn_id and p.context_mode in ('task_history_v1','knowledge_intent_v1','qa_session_history_v1')) order by created_at,turn_id limit 100 loop
    if not pg_try_advisory_xact_lock(hashtextextended(candidate.turn_id::text,195)) then continue; end if;
    if not turn_private.lock_turn(candidate.turn_id,candidate.owner_id,candidate.session_id) then
      perform turn_private.cancel_unclaimable_turn_v1(candidate.turn_id,candidate.owner_id);
      update turn_private.work set state='cancelled',lease_token=null,expires_at=null where turn_id=candidate.turn_id and state in ('queued','leased');
      return jsonb_build_object('kind','empty');
    end if;
    select * into w from turn_private.work where turn_id=candidate.turn_id for update;
    if not found or w.execution_mode<>'text' or w.state not in ('queued','leased') or (w.state='leased' and w.expires_at>clock_timestamp()) then return jsonb_build_object('kind','empty'); end if;
    select status into turn_state from public.turns where id=w.turn_id;
    if turn_state in ('completed','proposal_ready','unavailable','failed','cancelled') then perform turn_private.terminal(w.turn_id,'cancelled',w.attempt); return jsonb_build_object('kind','empty'); end if;
    if w.attempt>=w.max_attempts then perform turn_private.terminal(w.turn_id,'quarantined',w.attempt); return jsonb_build_object('kind','empty'); end if;
    update turn_private.work set state='leased',attempt=attempt+1,lease_token=gen_random_uuid(),expires_at=clock_timestamp()+w.lease_ms*interval '1 millisecond' where turn_id=w.turn_id returning * into w;
    return jsonb_build_object('kind','leased','turnId',w.turn_id,'ownerId',w.owner_id,'attempt',w.attempt,'leaseToken',w.lease_token,'leaseMs',w.lease_ms);
  end loop;
  return jsonb_build_object('kind','empty');
end $function$
;

CREATE OR REPLACE FUNCTION public.complete_grounded_place_work(p_turn_id uuid, p_lease_token uuid, p_intent text, p_request_scope text, p_unanswered_needs text, p_place_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source_text text; city text; needs jsonb; item jsonb; selected jsonb; result jsonb; final_intent text; final_scope text;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) then return place_actions_private.ask_complete_v1(p_turn_id,p_lease_token,p_intent,p_request_scope,p_unanswered_needs,p_place_name);end if;
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and place_actions_private.ask_bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) then return guide_private.place_complete_v1(p_turn_id,p_lease_token,p_intent,p_request_scope,p_unanswered_needs,p_place_name);end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','stale'); end if;
 if p_intent is null or p_intent not in ('place_address','place_opening_hours','place_address_and_hours')
  or p_request_scope is null or p_request_scope not in ('single','additional_needs')
  or p_place_name is null or length(p_place_name) not between 1 and 160 or p_place_name~'[[:cntrl:]]'
  or p_unanswered_needs is null or octet_length(p_unanswered_needs)>12000 then raise exception 'INVALID_INPUT'; end if;
 needs:=p_unanswered_needs::jsonb;
 if jsonb_typeof(needs) is distinct from 'array' then raise exception 'INVALID_INPUT'; end if;
 if jsonb_array_length(needs)>6 or ((p_request_scope='additional_needs')<>(jsonb_array_length(needs)>0)) then raise exception 'INVALID_INPUT'; end if;
 if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
 select c.input_text,g.city into source_text,city from turn_private.text_content c
 join turn_private.grounded_turns g on g.turn_id=c.turn_id and g.owner_id=c.owner_id where c.turn_id=p_turn_id and g.completed_at is null;
 if not found then return jsonb_build_object('kind','blocked'); end if;
 if strpos(source_text,p_place_name)=0 then raise exception 'INVALID_INPUT'; end if;
 for item in select value from jsonb_array_elements(needs) loop
  if jsonb_typeof(item)<>'string' or (item#>>'{}')!~'[^[:space:]]' or length(item#>>'{}')>240
   or strpos(source_text,item#>>'{}')=0 then raise exception 'INVALID_INPUT'; end if;
 end loop;
 if (select count(distinct value) from jsonb_array_elements(needs))<>jsonb_array_length(needs) then raise exception 'INVALID_INPUT'; end if;
 -- Same lock order as Ops: name barrier before publication row locks.
 perform pg_catalog.pg_advisory_xact_lock_shared(160047,1);
 begin
  selected:=knowledge_review_private.place_subject(p_place_name,city);
 exception when raise_exception then
  if SQLERRM<>'KNOWLEDGE_DISABLED' then raise; end if;
  return public.complete_grounded_work(p_turn_id,p_lease_token,'technical_failure','unknown');
 end;
 final_intent:=case selected->>'kind' when 'matched' then p_intent when 'ambiguous' then 'clarification' else 'unsupported' end;
 final_scope:=case when selected->>'kind'='matched' then p_request_scope else 'unknown' end;
 result:=turn_private.complete_selected_grounded_work(p_turn_id,p_lease_token,final_intent,final_scope,selected->>'subjectId');
 if result->>'kind'='finished' then
  update turn_private.grounded_turns set place_name=case when intent<>'technical_failure' then p_place_name end,
   place_resolution=case when intent<>'technical_failure' then selected->>'kind' end,
   unanswered_needs=case when request_scope='additional_needs' then needs else '[]'::jsonb end where turn_id=p_turn_id;
 end if;
 return result;
end $function$
;

CREATE OR REPLACE FUNCTION public.complete_grounded_work_with_needs(p_turn_id uuid, p_lease_token uuid, p_intent text, p_request_scope text, p_unanswered_needs text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare needs jsonb; source_text text; item jsonb; result jsonb;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and place_actions_private.ask_bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','stale'); end if;
 if p_unanswered_needs is null or octet_length(p_unanswered_needs)>12000 then raise exception 'INVALID_INPUT'; end if;
 needs:=p_unanswered_needs::jsonb;
 if jsonb_typeof(needs)<>'array' then raise exception 'INVALID_INPUT'; end if;
 if jsonb_array_length(needs)>6 or p_request_scope is null
  or ((p_request_scope='additional_needs') <> (jsonb_array_length(needs)>0)) then raise exception 'INVALID_INPUT'; end if;
 if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
 select input_text into source_text from turn_private.text_content where turn_id=p_turn_id;
 if source_text is null then return jsonb_build_object('kind','blocked'); end if;
 for item in select value from jsonb_array_elements(needs) loop
  if jsonb_typeof(item)<>'string' then raise exception 'INVALID_INPUT'; end if;
  if (item#>>'{}') !~ '[^[:space:]]' or length(item#>>'{}')>240
   or strpos(source_text,item#>>'{}')=0 then raise exception 'INVALID_INPUT'; end if;
 end loop;
 if (select count(distinct value) from jsonb_array_elements(needs))<>jsonb_array_length(needs) then raise exception 'INVALID_INPUT'; end if;
 -- The existing completion owns dispatch, current evidence, deadline recheck,
 -- immutable result and terminal event. Both writes commit or roll back together.
 result:=public.complete_grounded_work(p_turn_id,p_lease_token,p_intent,p_request_scope);
 if result->>'kind'='finished' then
  update turn_private.grounded_turns set unanswered_needs=case when request_scope='additional_needs' then needs else '[]'::jsonb end
   where turn_id=p_turn_id;
 end if;
 return result;
end $function$
;

CREATE OR REPLACE FUNCTION public.complete_text_work(p_turn_id uuid, p_lease_token uuid, p_kind text, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from turn_private.service_task_turns l join turn_private.service_tasks s on s.id=l.task_id where l.turn_id=p_turn_id and s.trip_objective is not null) then raise exception 'SERVICE_TASK_SCOPE_CONFLICT';end if;
 if exists(select 1 from turn_private.service_task_turns where turn_id=p_turn_id) and not turn_private.lock_trip_account_v1((select owner_id from turn_private.service_task_turns where turn_id=p_turn_id)) then return jsonb_build_object('kind','blocked');end if;
 return public.complete_text_work_before_trip_v1(p_turn_id,p_lease_token,p_kind,p_text);
end $function$
;

CREATE OR REPLACE FUNCTION conversation_data_private.schema_supported_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare s record;actual_n text[];pk_n text[];foreign_n jsonb;column_specs jsonb;
begin
 if place_actions_private.ask_schema_v1() is not true then return false;end if;
 if not turn_private.directions_schema_members_v1() then return false;end if;
 for s in select * from conversation_data_private.sources_v1() loop
  if to_regclass(s.relation_name) is null then return false;end if;
  select array_agg(attname::text order by attnum) into actual_n from pg_attribute where attrelid=s.relation_name::regclass and attnum>0 and not attisdropped and not(attrelid='turn_private.grounded_turns'::regclass and attname='selected_place_request');
  if actual_n is distinct from s.columns_n then return false;end if;
  select array_agg(a.attname::text order by key.ordinality) into pk_n from pg_constraint c
   cross join lateral unnest(c.conkey) with ordinality key(attnum,ordinality)
   join pg_attribute a on a.attrelid=c.conrelid and a.attnum=key.attnum where c.conrelid=s.relation_name::regclass and c.contype='p';
  if pk_n is distinct from s.pk then return false;end if;
 end loop;
 select jsonb_object_agg(relation_name,cols) into column_specs from (
  select source_spec.relation_name,jsonb_agg(jsonb_build_object('name',a.attname,'type',a.atttypid::regtype::text,'notNull',a.attnotnull) order by a.attnum) cols
  from conversation_data_private.sources_v1() source_spec join pg_attribute a on a.attrelid=source_spec.relation_name::regclass
  where a.attnum>0 and not a.attisdropped and not(a.attrelid='turn_private.grounded_turns'::regclass and a.attname='selected_place_request') group by source_spec.relation_name
 ) metadata;
 if column_specs is distinct from '{"public.chat_threads":[{"name":"id","type":"uuid","notNull":true},{"name":"owner_id","type":"uuid","notNull":true},{"name":"trip_id","type":"uuid","notNull":false},{"name":"status","type":"text","notNull":true},{"name":"created_at","type":"timestamp with time zone","notNull":true},{"name":"updated_at","type":"timestamp with time zone","notNull":true}],"public.chat_turn_events":[{"name":"id","type":"uuid","notNull":true},{"name":"owner_id","type":"uuid","notNull":true},{"name":"thread_id","type":"uuid","notNull":true},{"name":"turn_id","type":"uuid","notNull":true},{"name":"event_id","type":"text","notNull":true},{"name":"sequence","type":"integer","notNull":true},{"name":"schema_version","type":"text","notNull":true},{"name":"event_type","type":"text","notNull":true},{"name":"state","type":"text","notNull":true},{"name":"created_at","type":"timestamp with time zone","notNull":true}],"public.chat_turn_idempotency":[{"name":"owner_id","type":"uuid","notNull":true},{"name":"thread_id","type":"uuid","notNull":true},{"name":"idempotency_key","type":"text","notNull":true},{"name":"digest","type":"text","notNull":true},{"name":"turn_id","type":"uuid","notNull":true},{"name":"created_at","type":"timestamp with time zone","notNull":true}],"public.memory_consumer_receipts":[{"name":"id","type":"uuid","notNull":true},{"name":"owner_id","type":"uuid","notNull":true},{"name":"memory_id","type":"uuid","notNull":true},{"name":"source_receipt_id","type":"uuid","notNull":true},{"name":"consumer_kind","type":"text","notNull":true},{"name":"turn_id","type":"uuid","notNull":false},{"name":"proposal_id","type":"uuid","notNull":false},{"name":"constraint_kind","type":"text","notNull":true},{"name":"created_at","type":"timestamp with time zone","notNull":true}],"public.model_budget_attempts":[{"name":"scope_id","type":"uuid","notNull":true},{"name":"attempt_id","type":"uuid","notNull":true},{"name":"task_id","type":"uuid","notNull":true},{"name":"provid