CREATE OR REPLACE FUNCTION turn_data_private.schema_supported_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare actual_n jsonb;s record;pk_n text[];
begin
 if place_actions_private.ask_schema_v1() is not true then return false;end if;

 -- QA v1 accepts exactly the authored extensions; every other schema member stays in the original digest.
 if (select pg_get_constraintdef(k.oid) from pg_constraint k where k.conrelid='turn_private.text_policies'::regclass and k.conname='text_policies_context_mode_check') is distinct from 'CHECK ((context_mode = ANY (ARRAY[''current_input_v1''::text, ''task_history_v1''::text, ''knowledge_intent_v1''::text, ''qa_session_history_v1''::text])))' then return false;end if;
 if (select pg_get_constraintdef(k.oid) from pg_constraint k where k.conrelid='turn_private.service_task_turns'::regclass and k.conname='service_task_turns_relationship_check') is distinct from 'CHECK ((relationship = ANY (ARRAY[''new_goal''::text, ''clarification''::text, ''repair''::text, ''qa_followup''::text, ''qa_correction''::text])))' then return false;end if;
 if not turn_private.directions_schema_members_v1() then return false;end if;
 for s in select * from turn_data_private.sources_v1() loop
  if to_regclass(s.relation_name) is null then return false;end if;
  select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull) order by a.attnum) into actual_n from pg_attribute a where a.attrelid=s.relation_name::regclass and a.attnum>0 and not a.attisdropped and not(a.attrelid='turn_private.grounded_turns'::regclass and a.attname='selected_place_request');
  if actual_n is distinct from ('{"public.chat_turn_events":[{"name":"id","type":"uuid","notNull":true},{"name":"owner_id","type":"uuid","notNull":true},{"name":"thread_id","type":"uuid","notNull":true},{"name":"turn_id","type":"uuid","notNull":true},{"name":"event_id","type":"text","notNull":true},{"name":"sequence","type":"integer","notNull":true},{"name":"schema_version","type":"text","notNull":true},{"name":"event_type","type":"text","notNull":true},{"name":"state","type":"text","notNull":true},{"name":"created_at","type":"timestamp with time zone","notNull":true}],"public.chat_turn_idempotency":[{"name":"owner_id","type":"uuid","notNull":true},{"name":"thread_id","type":"uuid","notNull":true},{"name":"idempotency_key","type":"text","notNull":true},{"name":"digest","type":"text","notNull":true},{"name":"turn_id","type":"uuid","notNull":true},{"name":"created_at","type":"timestamp with time zone","notNull":true}],"public.memory_consumer_receipts":[{"name":"id","type":"uuid","notNull":true},{"name":"owner_id","type":"uuid","notNull":true},{"name":"memory_id","type":"uuid","notNull":true},{"name":"source_receipt_id","type":"uuid","notNull":true},{"name":"consumer_kind","type":"text","notNull":true},{"name":"turn_id","type":"uuid","notNull":false},{"name":"proposal_id","type":"uuid","notNull":false},{"name":"constraint_kind","type":"text","notNull":true},{"name":"created_at","type":"timestamp with time zone","notNull":true}],"public.model_budget_attempts":[{"name":"scope_id","type":"uuid","notNull":true},{"name":"attempt_id","type":"uuid","notNull":true},{"name":"task_id","type":"uuid","notNull":true},{"name":"provider","type":"text","notNull":true},{"name":"model","type":"text","notNull":true},{"name":"price_version","type":"text","notNull":true},{"name":"reserved_micros","type":"bigint","notNull":true},{"name":"actual_micros","type":"bigint","notNull":false},{"name":"status","type":"text","notNull":true},{"name":"created_at","type":"timestamp with time zone","notN